import csv
import io
import logging
import re

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CellMapping(object):

    def get_cell_mapping(self, name):
        """
        Returns cell mapping from AaShell in dict format

        :param str name: alias name
        :return: cell mapping as dict
        """
        process_node_suffix = self._extract_process_node_suffixes(name, command='getCellMapping')[0]
        if not process_node_suffix:
            raise Exception("ERROR: Cannot find process which supports getCellMapping command in known nodes")
        output = self.execute_aashell_command(
            name=name,
            command='getCellMapping{process_node_suffix}'.format(process_node_suffix=process_node_suffix)).strip()
        csv_string = re.sub(
            r" +",
            r",",
            "\n".join([line.strip() for line in output.splitlines()]))
        return {
            d['lcr']: d
            for d in csv.DictReader(io.StringIO(csv_string))}
